datatype chol =
  | NoSPD of ()
  | Chol of (double, double, double)

fn cholesky2 (a: double, b: double, d: double): chol =
  if a <= 0.0 then NoSPD ()
  else let
    val l11 = c_sqrt (a)
    val l21 = d_div (b, l11)
    val s = d_sub (d, d_mul (l21, l21))
  in
    if s <= 0.0 then NoSPD () else Chol (l11, l21, c_sqrt (s))
  end

fn mostrar (r: chol): void =
  case+ r of
  | NoSPD () => println! ("no es definida positiva")
  | Chol (l11, l21, l22) => (pd (l11); pd (l21); pd (l22))

implement main0 () = {
