def dot [n] (x: [n]f64) (y: [n]f64) : f64 = reduce (+) 0 (map2 (*) x y)
def matvec [m][n] (a: [m][n]f64) (v: [n]f64) : [m]f64 = map (\f -> dot f v) a
def norma [n] (x: [n]f64) : f64 = f64.sqrt (dot x x)

def potencia [n] (iters: i64) (a: [n][n]f64) (v0: [n]f64) : f64 =
  let v = loop v = v0 for _i < iters do
            let w = matvec a v
            in map (/ norma w) w
  in dot v (matvec a v)

futhark> potencia 50 [[2.0, 1.0], [1.0, 2.0]] [1.0, 0.0]

